-- Import des courriers arrivées 2004
-- Source : 2004.xlsx (feuille 2004), 2236 courriers.
--
-- Correspondance Excel -> table arrivees (formulaire arrivee/create.vue)
--   N°              -> txt_numdordre (00001/jj-mm-aaaa) et txt_numcourier
--   DATE RECEPTION  -> dt_datearrivee et dt_datecourier
--   PRENOMS + NOM   -> txt_prenomNom et txt_expediteur
--   DESIGNATIONS    -> txt_objet (texte dorigine du classeur)
--   DESIGNATIONS    -> txt_designation (entrée de la liste du formulaire)
--   txt_designation -> txt_categorie (designationsParCategorie)
--   N° TF           -> txt_numTitreFoncier
--   N° LOT          -> txt_numLot
--   AGENTS TRAITEUR -> txt_agenttraiteur
--   OBSERVATIONS    -> txt_observation
--   référence       -> "<N°> du jj-mm-aaaa"
--
-- La colonne CATEGORIES du classeur vaut partout "Demande SERVICES" : elle est recalculée.
-- Absents du classeur : txt_typecourrier = Individuel, txt_nombrepiece = 1.
-- Un courrier sans agent (n° 1955) reçoit "Non renseigné".
-- Références en doublon : suffixe du N° TF.
-- Convocation : date et heure reprises dans lobjet quand elles y figurent.

SET NAMES utf8mb4;

ALTER TABLE `arrivees`
  MODIFY `txt_numTitreFoncier` VARCHAR(255) NULL;

START TRANSACTION;


COMMIT;
